Given an array arr[] of positive integers and a value k, you can perform at most k operations. In each operation, you may increment any one element of the array by 1. Find the maximum median that can be achieved after performing at most k such operations.Note: If the array has even length, the median is calculated as (arr[n/2] + arr[n/2 - 1]) / 2 after sorting the array.Example:Input: arr[] = [1, 3, 4, 5], k = 3Output: 5Explanation: We can add +2 to the second element and +1 to the third element to get the array [1, 5, 5, 5]. After sorting, the array remains [1, 5, 5, 5]. Since the length is even, the median is (5 + 5) / 2 = 5.Input: arr[] = [1, 3, 6, 4, 2], k = 10Output: 7Explanation: After applying operations optimally, we can transform the array to [1, 3, 7, 7, 7] (one possible way). Sorted array becomes [1, 3, 7, 7, 7]. Since the length is odd, the median is the middle element 7.Try It YourselfTable of Content[Naive Approach] Linear Scan over Answer Space - O(n × k ) Time and O(1) Space[Expected Approach] Binary Search on Answer[Naive Approach] Linear Scan over Answer Space - O(n × k ) Time and O(1) SpaceThe idea is to try every possible median value from the current median up to currentMedian + k, and check if we can make the median at least that value using ≤ k operations.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// check if we can make median at least 'target' 
// with <= k operations
bool isPossible(vector<int>& arr, int target, int k){
    int n = arr.size();
    int used = 0;

    if (n % 2 == 1) {
        // for odd-sized array, update elements 
        // from middle to end
        for (int i = n / 2; i < n; ++i) {
            if (arr[i] < target)
                used += (target - arr[i]);
            if(used > k) break;
        }
    } else {
        // for even-sized array, handle two 
        // middle elements
        if (arr[n / 2] <= target) {
            used += (target - arr[n / 2]);
            used += (target - arr[n / 2 - 1]);
        } 
        else {
            used += (2 * target - 
                    (arr[n / 2] + arr[n / 2 - 1]));
        }
        // process remaining elements to the right
        for (int i = n / 2 + 1; i < n; ++i) {
            if (arr[i] < target)
                used += (target - arr[i]);

            if(used > k) break;
        }
    }

    return used <= k;
}

int maximizeMedian(vector<int>& arr, int k){
    int n = arr.size();
    sort(arr.begin(), arr.end());

    // compute current median
    int iniMedian = arr[n / 2];
    if (n % 2 == 0) {
        iniMedian += arr[n / 2 - 1];
        iniMedian /= 2;
    }

    int best = iniMedian;

    // try all possible medians from currMedian 
    // to currMedian + k
    for (int target = iniMedian;
                target <= iniMedian + k; ++target){
        if (isPossible(arr, target, k))
            best = target;
    }

    return best;
}

int main() {
    vector<int> arr = {1, 3, 4, 5};
    int k = 3;

    int result = maximizeMedian(arr, k);
    cout << result << endl;

    return 0;
}


